@Catch()
export class AllExceptionsFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const res = host.switchToHttp().getResponse();
    // BUG 1: no res.status(...) -> Express defaults to 200
    // BUG 2: leaks the raw stack straight to the client
    // BUG 3: no requestId, no server-side log
    res.json({ message: (exception as Error).stack });
  }
}

