catch(exception: unknown, host: ArgumentsHost) {
  const ctx = host.switchToHttp();
  const res = ctx.getResponse<Response>();
  const req = ctx.getRequest<Request>();
  const status =
    exception instanceof HttpException
      ? exception.getStatus()
      : HttpStatus.INTERNAL_SERVER_ERROR;
  const requestId = getRequestId();

  // log ONCE at the boundary, full stack + context, server-side only
  this.logger.error({ requestId, path: req.url, status, err: exception },
    exception instanceof Error ? exception.stack : 'non-error thrown');

  const message =
    status === HttpStatus.INTERNAL_SERVER_ERROR
      ? 'Internal server error'                 // generic on 500 — no leak
      : (exception as HttpException).getResponse();

  res.status(status).json({                     // status() is load-bearing
    statusCode: status, message,
    timestamp: new Date().toISOString(),
    path: req.url, requestId,
  });
}

Why: res.status(status).json(...) fixes the 200; computing status from getStatus()/500 sets the real code; returning a generic message on 500 (while logging the full stack server-side) stops the information-disclosure leak; and reading getRequestId() from AsyncLocalStorage puts the same correlation id on the log line and the envelope. Logging exactly once here avoids the triple-logged stack from handlers re-throwing.

